package core

import (
	"github.com/jokruger/kavun/core/member"
	"github.com/jokruger/kavun/errs"
	"github.com/jokruger/kavun/fspec"
	"github.com/jokruger/kavun/internal/text"
)

// error's members: one function per member, each declared by the //kavun:member directive in its doc comment. The
// table, errorMethods, and the member entries of docs/reference/types/error.md (alphabetical, so the order here is
// free) are generated by cmd/kavun-gen — run `go generate ./...` after changing a directive or a doc comment.

// Render the value per the [format mini-language](../../format_mini_language.md).
//
// The universal render. The default form renders the payload — whatever its type, exactly as `string()` does;
// `"v"` shows the constructor form. An f-string, `format(...)` and `json.encode` all go through this render, so
// `json.encode(e)` is `{"error": <the default render>}`, the render encoded exactly as a `string` is — escaped, and
// raising `json_encoding` when it holds octets that are not symbols.
//
// ```go
// error("boom").format()      // => "boom"
// error([1, 2]).format()      // => "[1, 2]" — a non-string payload renders as its string form
// error("boom").format("v")   // => "error(\"boom\")"
// ```
//
//kavun:member format pure ([spec]) -> string
func errorFormat(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return FormatWithSpec(v, id, args)
}

// Report truthiness, which is always `true` for an error; see [`bool`](#bool).
//
//kavun:member is_true pure () -> bool
func errorIsTrue(_ VM, v Value, _ member.ID, _ []Value) (Value, error) {
	t, err := ValueTypes[v.Type].IsTrue(v)
	if err != nil {
		return Undefined, err
	}
	return BoolValue(t), nil
}

// Answer `true`: every error is truthy, whatever its payload.
//
// Both answer `true` for every error — truthiness is the single stated base case: an error is always truthy,
// payload or no payload. `bool()` does **not** parse the payload.
//
// ```go
// error(0).is_true()        // => true
// error(0).bool()           // => true
// error("false").bool()     // => true — not a payload parse
// error(undefined).is_true() // => true
// ```
//
// The `default` is taken for interface uniformity — every conversion carries it — and is never used: the
// conversion is total.
//
//kavun:member bool pure ([default]) -> bool
func errorBool(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	b, _ := v.AsBool()
	return ConvMember(id.String(), errorTypeName, args, true, BoolValue(b))
}

// Answer an error with a deep copy of the payload.
//
// Real deep operations on the payload — not header no-ops. `copy()` answers an error with a deep copy of the
// payload; `freeze()` answers an error whose payload is deep-frozen (the receiver is unchanged).
//
// ```go
// e := error([1, 2])
// c := e.copy()
// c.value().push_in_place(3)
// format(c.value())              // => "[1, 2, 3]"
// format(e.value())              // => "[1, 2]" — the original payload untouched
//
// fe := e.freeze()
// is_immutable(fe.value())       // => true
// is_immutable(e.value())        // => false
// ```
//
//kavun:member copy pure () -> error
func errorCopy(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return errorTypeCopy(v, true)
}

// Answer an error whose payload is deep-frozen, leaving the receiver unchanged; see [`copy`](#copy).
//
//kavun:member freeze pure () -> error
func errorFreeze(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return v.Freeze()
}

// Answer the payload, exactly as wrapped.
//
// The payload, exactly as wrapped — and the ONLY structured channel an error has. `kind()` is a tag; there is no
// further field set on a runtime error.
//
// | the error came from | `value()` is |
// | --- | --- |
// | the runtime (a builtin, member, module) | the message `string`, always non-empty: `1/0`'s is `"division by zero"` |
// | `error(x)` / `raise(x)` | `x`, untouched — any type |
// | `require(cond, x)` | `x`, untouched — any type |
//
// ```go
// error(42).value()          // => 42
// error(undefined).value()   // => undefined
// ```
//
// So a script that wants to hand a structured rejection to its host raises one:
//
// ```go
// amount := 5d                          // the host's binding
// require(amount > 0d, {field: "amount", reason: "must be positive"})
// // host: re.Payload is that record, not a sentence to re-parse
// ```
//
//kavun:member value pure () -> value
func errorValue(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	o := (*Error)(v.Ptr)
	return o.Payload, nil
}

// Answer the machine-readable tag, a `string`.
//
// The machine-readable tag, a `string`. Constructed and `raise`d errors are `"user"`; runtime errors carry the
// tags in the [kind table](#every-error-kind) below. This is the value a handler matches on.
//
// ```go
// error("boom").kind()          // => "user"
// error("boom", true).kind()    // => "user" — the fatal flag is not a kind
// ```
//
//kavun:member kind pure () -> string
func errorKind(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	o := (*Error)(v.Ptr)
	return NewStringValue(o.Kind), nil
}

// Report whether the runtime raised the error — a builtin, a member function or a stdlib module.
//
// The [category](#categories) predicates — where the error came from. Exactly one is `true` for any error a
// script can hold.
//
// ```go
// error("boom").is_user()            // => true
// error("boom").is_runtime()         // => false
// error("boom").is_requirement()     // => false
//
// zero := 0
// e := func() r { defer func() { r = recover() }(); 1 / zero }()   // a recovered 1/0 error
// e.kind()                            // => "division_by_zero"
// e.is_runtime()                      // => true
//
// e = func() r { defer func() { r = recover() }(); require(false, {field: "amount"}) }()   // a recovered require
// e.kind()                            // => "requirement"
// e.is_requirement()                  // => true
// e.value()                           // => {"field": "amount"} — the payload, untouched
// ```
//
// There is no `is_system()`: a system error is always fatal and never reaches a script. There is no `is_fatal()`
// either — the fatal flag's only reader is the host (`RuntimeError.Fatal`). A script *sets* it, with
// `error(x, true)` or `raise(x, true)`, and can never read it back off a caught error, because a caught error
// is recoverable by construction.
//
//kavun:member is_runtime pure () -> bool
func errorIsRuntime(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	o := (*Error)(v.Ptr)
	return BoolValue(o.Category == errs.CategoryRuntime), nil
}

// Report whether the script built the error with `error(...)` / `raise(...)`; see [`is_runtime`](#is_runtime).
//
//kavun:member is_user pure () -> bool
func errorIsUser(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	o := (*Error)(v.Ptr)
	return BoolValue(o.Category == errs.CategoryUser), nil
}

// Report whether the script raised the error with `require(cond, payload)`; see [`is_runtime`](#is_runtime).
//
//kavun:member is_requirement pure () -> bool
func errorIsRequirement(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	o := (*Error)(v.Ptr)
	return BoolValue(o.Category == errs.CategoryRequirement), nil
}

// Render the payload as a `string`, the same path `format()` uses.
//
// The **payload's** render — the same path `format()` uses — as `string`/`runes`. This is a render of the
// content, not a laundering conversion: the result describes the payload, whatever its type. The free
// `string(e)` matches.
//
// ```go
// error("boom").string()   // => "boom"
// error(42).string()       // => "42"
// error("boom").runes()    // => u"boom"
// string(error(42))        // => "42"
// ```
//
// A payload with no rendering (a host value without a `format`) raises, or answers the `default` when one is
// given.
//
//kavun:member string pure ([default]) -> string
func errorString(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	if len(args) > 1 {
		return Undefined, ErrArgCount
	}
	s, err := (*Error)(v.Ptr).Payload.Format(fspec.FormatSpec{})
	if err != nil {
		if len(args) == 1 {
			return args[0], nil
		}
		return Undefined, err
	}
	return NewStringValue(s), nil
}

// Render the payload as `runes`; see [`string`](#string).
//
// As for [`string`](#string), the `default` is answered only when the payload has no rendering.
//
//kavun:member runes pure ([default]) -> runes
func errorRunes(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	if len(args) > 1 {
		return Undefined, ErrArgCount
	}
	s, err := (*Error)(v.Ptr).Payload.Format(fspec.FormatSpec{})
	if err != nil {
		if len(args) == 1 {
			return args[0], nil
		}
		return Undefined, err
	}
	return NewRunesValue(text.DecodeText(s), false), nil
}
